const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout,
    terminal: false
});

let n = 0;
let count = 0;
const right = new Array(61).fill(0);
const left = new Array(61).fill(0);
let expected = -1;

rl.on('line', (line) => {
    const parts = line.trim().split(/\s+/);
    if (parts.length === 1 && expected === -1) {
        n = parseInt(parts[0]);
        expected = n;
        return;
    }
    if (parts.length < 2) return;
    const m = parseInt(parts[0]);
    const l = parts[1];
    if (l === 'D') right[m]++;
    else left[m]++;
    count++;
    if (count === expected) {
        let total = 0;
        for (let i = 30; i <= 60; i++) {
            total += Math.min(right[i], left[i]);
        }
        console.log(total);
        rl.close();
    }
});
